    // the crowd control a skill description names, with its level from the State Guide
    // ("knock" / "knocked back" = Displacement, "airborne" / "knock up" = Airborne, "slow" = slow)
    private val ccWords = listOf(
        "suppress" to "Suppress", "frozen moment" to "Frozen Moment", "airborne" to "Airborne", "knock up" to "Airborne",
        "knocks up" to "Airborne", "petrif" to "Petrify", "freez" to "Freeze", "frozen" to "Freeze", "transform" to "Transform",
        "stun" to "Stun", "silence" to "Silence", "terrif" to "Terrify", "fear" to "Terrify", "taunt" to "Taunt",
        "immobiliz" to "Immobilize", "root" to "Root", "restrain" to "Restrain", "disarm" to "Disarm",
        "knock back" to "Displacement", "knocked back" to "Displacement", "knocks back" to "Displacement",
        "pull" to "Pull", "gather" to "Displacement")
    fun ccIn(description: String): List<String> {
        val t = description.lowercase()
        return ccWords.filter { (w, _) -> w in t }.map { it.second }.distinct().let { l ->
            // "transform" in an ultimate that transforms the hero itself is not crowd control
            if ("Transform" in l && !Regex("transforms? (the )?(target|enem)").containsMatchIn(t)) l - "Transform" else l
        }.map { n -> n + (states.firstOrNull { it.name == n }?.group?.let { g -> " ($g)" } ?: "") } +
            (if ("slow" in t) listOf("Slow") else emptyList())
    }
    // Purify / Control Immunity do not help against these (State Guide: "Cannot be removed",
    // Control Immunity excludes Suppression)
    val unremovable = setOf("Suppress", "Frozen Moment")
}
